def countRoutesWithTurns(grid, k):
    MOD = 10 ** 9 + 7
    m, n = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[m - 1][n - 1] == 1:
        return 0
    if m == 1 and n == 1:
        return 1 if k == 0 else 0
    zero = [0] * (k + 1)
    R = [[zero] * n for _ in range(m)]
    D = [[zero] * n for _ in range(m)]
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                continue
            nr = zero[:]
            nd = zero[:]
            if c > 0:
                if r == 0 and c == 1:
                    nr[0] = 1
                else:
                    pr, pd = R[r][c - 1], D[r][c - 1]
                    for t in range(k + 1):
                        nr[t] = (pr[t] + (pd[t - 1] if t else 0)) % MOD
            if r > 0:
                if r == 1 and c == 0:
                    nd[0] = 1
                else:
                    pr, pd = R[r - 1][c], D[r - 1][c]
                    for t in range(k + 1):
                        nd[t] = (pd[t] + (pr[t - 1] if t else 0)) % MOD
            R[r][c] = nr
            D[r][c] = nd
    return (R[m - 1][n - 1][k] + D[m - 1][n - 1][k]) % MOD
